import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.CdvW4CUT.js";const g=JSON.parse('{"title":"安全与权限","description":"CertHub 的账号密码策略、两步验证、用户组权限、凭据加密、审计日志与生产加固清单。","frontmatter":{"title":"安全与权限","description":"CertHub 的账号密码策略、两步验证、用户组权限、凭据加密、审计日志与生产加固清单。"},"headers":[],"relativePath":"docs/security.md","filePath":"docs/security.md","lastUpdated":null}'),s={name:"docs/security.md"};function i(r,t,l,c,n,h){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="安全与权限" tabindex="-1">安全与权限 <a class="header-anchor" href="#安全与权限" aria-label="Permalink to &quot;安全与权限&quot;">​</a></h1><h2 id="账号与密码" tabindex="-1">账号与密码 <a class="header-anchor" href="#账号与密码" aria-label="Permalink to &quot;账号与密码&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>默认值</th><th>在哪改</th></tr></thead><tbody><tr><td>密码强度</td><td>≥8 位、不能是纯数字、不能与用户名相同</td><td>注册 / 建用户 / 改密 / 管理员重置四处统一校验</td></tr><tr><td>登录失败上限</td><td>5 次</td><td>系统设置 → 安全</td></tr><tr><td>锁定时长</td><td>10 分钟</td><td>系统设置 → 安全</td></tr><tr><td>图形验证码</td><td>失败 1 次后开始要求</td><td>系统设置 → 安全</td></tr><tr><td>强制两步验证</td><td>关闭</td><td>系统设置 → 安全</td></tr><tr><td>自助注册</td><td><strong>关闭</strong></td><td>系统设置 → 站点信息</td></tr><tr><td>登录提醒</td><td>开启（有邮箱 + 配了邮件渠道才发）</td><td>系统设置 → 安全</td></tr></tbody></table><ul><li>改密成功后会被<strong>强制要求重新登录</strong>（旧 token 在过期前仍有效，换身份才安全）。</li><li><strong>忘记密码</strong>：系统不带邮件找回。管理员可在 <strong>用户管理 → 重置密码</strong> 给任何账号重置，支持一键生成 16 位随机强密码；重置会同时清除该账号的失败锁定。</li><li>两步验证码输错也计入登录失败次数 —— 否则 6 位数字可以被无限爆破。</li></ul><h2 id="两步验证-totp" tabindex="-1">两步验证（TOTP） <a class="header-anchor" href="#两步验证-totp" aria-label="Permalink to &quot;两步验证（TOTP）&quot;">​</a></h2><p><strong>账号安全 → 两步验证</strong>，扫码绑定（也支持手动输入密钥），输入一次动态口令即生效。换手机时用同一张二维码再加一台设备。</p><div class="tip custom-block"><p class="custom-block-title">建议</p><p>管理员账号一律开 2FA；公网可达的部署可以在系统设置里打开「强制两步验证」，对所有账号生效。</p></div><h2 id="用户与权限" tabindex="-1">用户与权限 <a class="header-anchor" href="#用户与权限" aria-label="Permalink to &quot;用户与权限&quot;">​</a></h2><ul><li>角色两级：<strong>管理员</strong>（系统设置、用户管理、审计日志、开放接口）+ <strong>普通用户</strong>（自己的流水线、证书、授权）。</li><li><strong>数据按用户隔离</strong>：流水线、证书、授权、通知渠道都带 <code>user_id</code>，普通用户互相看不到。</li><li><strong>用户组</strong>可以按功能键授权，例如只给某人 <code>pipelines</code> + <code>certs</code>，不给 <code>access</code>（看不到凭据）与 <code>settings</code>。</li></ul><p>功能权限键与侧边栏一一对应：<code>pipelines</code> / <code>history</code> / <code>certs</code> / <code>access</code> / <code>dns</code> / <code>monitor</code> / <code>notifications</code>，系统类页面（设置、用户、审计、开放接口）仅管理员可见。</p><h2 id="凭据怎么存、怎么显示" tabindex="-1">凭据怎么存、怎么显示 <a class="header-anchor" href="#凭据怎么存、怎么显示" aria-label="Permalink to &quot;凭据怎么存、怎么显示&quot;">​</a></h2><p>这是本项目和很多同类系统<strong>刻意不同</strong>的地方，需要提前知道：</p><table tabindex="0"><thead><tr><th>环节</th><th>做法</th></tr></thead><tbody><tr><td>数据库</td><td>凭据、证书私钥用 <strong>AES-GCM 加密存储</strong>（<code>security.encrypt_json</code>）</td></tr><tr><td>接口</td><td><strong>明文返回</strong>，不在接口层打码 —— 排障时能确认到底填了什么</td></tr><tr><td>界面</td><td>密码框默认星号，点「小眼睛」显示明文</td></tr><tr><td>编辑</td><td>留空 = 不修改，后端还原旧值，<strong>绝不会把密钥写成空串</strong></td></tr><tr><td>日志</td><td>错误信息只保留主机名，token 不进日志</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">由此带来的责任</p><p>因为接口是明文返回，<strong>数据库文件与备份文件本身必须当机密文件对待</strong>：限制目录权限、不要放进公共网盘 / 公开仓库、备份加密存放。</p></div><h2 id="审计日志" tabindex="-1">审计日志 <a class="header-anchor" href="#审计日志" aria-label="Permalink to &quot;审计日志&quot;">​</a></h2><p><strong>审计日志</strong> 记录关键操作：谁、什么时候、对什么做了什么（创建 / 修改 / 删除流水线、授权、用户、重置密码、创建 API 密钥等）。排「这条流水线是谁改坏的」时先看这里。</p><h2 id="接口与网络" tabindex="-1">接口与网络 <a class="header-anchor" href="#接口与网络" aria-label="Permalink to &quot;接口与网络&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>/api/docs</code></td><td><strong>关闭</strong></td><td>只在本机调试时用 <code>CERTD_DOCS=1</code> 打开</td></tr><tr><td>CORS</td><td><code>*</code></td><td>上线改成实际域名（<code>CERTD_CORS_ORIGINS</code>）</td></tr><tr><td>请求体上限</td><td>21 MB</td><td>够导入证书与上传 Logo</td></tr><tr><td>安全响应头</td><td>已内置</td><td><code>nosniff</code> / <code>SAMEORIGIN</code> / <code>no-referrer</code> / <code>Permissions-Policy</code>，HTTPS 额外发 HSTS</td></tr><tr><td>CSP</td><td><strong>未启用</strong></td><td>前端有内联样式与 <code>data:</code> 图片，需要单独联调</td></tr><tr><td>健康检查</td><td><code>/api/health</code></td><td>数据库 / 磁盘 / 调度器异常时返回 503</td></tr></tbody></table><h2 id="开放接口的密钥" tabindex="-1">开放接口的密钥 <a class="header-anchor" href="#开放接口的密钥" aria-label="Permalink to &quot;开放接口的密钥&quot;">​</a></h2><p><strong>开放接口</strong> 里可以创建 API 密钥（<code>ck_</code> 开头 + secret），调用时放在请求头：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-api-key: ck_xxx&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-api-secret: yyy&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     http://127.0.0.1:8000/api/open/v1/pipelines</span></span></code></pre></div><ul><li>密钥只能看到<strong>自己账号</strong>的数据。</li><li>secret 只在创建时返回一次，之后不可再查 —— 丢了就删掉重建。</li><li>删除密钥立即失效（<code>lastUsedTime</code> 可以看到是否还在被使用）。</li></ul><h2 id="生产加固清单" tabindex="-1">生产加固清单 <a class="header-anchor" href="#生产加固清单" aria-label="Permalink to &quot;生产加固清单&quot;">​</a></h2><ol><li>改掉默认密码，管理员开 2FA，公网部署考虑「强制两步验证」。</li><li>上 HTTPS，反向代理层限制后台访问来源 IP。</li><li><code>CERTD_SECRET_KEY</code> 写死并备份；<code>data/secret.key</code> 不要删。</li><li>固定数据目录权限（仅服务账号可读），备份文件加密。</li><li>关闭自助注册（默认就是关的），需要多人协作时再开。</li><li>云厂商用子账号 AK，只给 DNS / CDN 证书相关权限。</li><li>盯住 <code>/api/health</code> 与磁盘剩余空间。</li></ol><div class="warning custom-block"><p class="custom-block-title">残余风险（已知）</p><ul><li>未启用 CSP：前端有内联样式与 <code>data:</code> 图片，需要单独联调后再开。</li><li>凭据接口明文返回是产品设计（便于排障），只能靠数据库与备份文件的访问控制兜底。</li><li>不带邮件找回密码，忘记密码只能由管理员重置。</li></ul></div>`,25)])])}const u=d(s,[["render",i]]);export{g as __pageData,u as default};
